import * as THREE from 'three/webgpu';
import { texture as tsTexture } from 'three/tsl';

interface NodeConfig {
  imageUrl: string;
  depthMapUrl?: string | null;
  meshUrl?: string | null;
  atlasRegion?: {
    atlas: number;
    x: number;
    y: number;
    width: number;
    height: number;
    atlasWidth?: number;
    atlasHeight?: number;
  };
  cinematicPrimitives?: Array<{ name: string; params: any }>;
  scenePosition?: { x: number; y: number; z: number };
  [key: string]: any;
}

interface NodeContext {
  textureLoader: any;
  glbLoader: any;
  fontAtlas: any;
  primitives: Record<string, (obj: THREE.Object3D, params: any) => void>;
}

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const group = new THREE.Group();

  // Load texture synchronously from cache
  const textureData = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry with aspect ratio 512/320 = 1.6
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Handle atlas region UV mapping
  if (config.atlasRegion) {
    const region = config.atlasRegion;
    const atlasWidth = region.atlasWidth || 512;
    const atlasHeight = region.atlasHeight || 320;

    const uOffset = region.x / atlasWidth;
    const vOffset = region.y / atlasHeight;
    const uScale = region.width / atlasWidth;
    const vScale = region.height / atlasHeight;

    const uvAttribute = geometry.attributes.uv as THREE.BufferAttribute;
    for (let i = 0; i < uvAttribute.count; i++) {
      const u = uvAttribute.getX(i);
      const v = uvAttribute.getY(i);
      uvAttribute.setXY(i, uOffset + u * uScale, vOffset + v * vScale);
    }
    uvAttribute.needsUpdate = true;
  }

  // Create material using TSL texture node
  const textureNode = tsTexture(textureData);
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = textureNode;

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x,
      config.scenePosition.y,
      config.scenePosition.z
    );
  }

  // Setup cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Texture is managed by ctx.textureLoader cache, do not dispose
  };

  // Initialize handlers object
  group.userData.handlers = {};

  return group;
}
